  @media (max-width: 760px) { .workspace { grid-template-columns: 58px minmax(0,1fr); } .page-rail { padding-inline: 7px; } .rail-title span, .rail-section, .page-link span { display: none; } .page-link, .page-link.sub { padding: 6px; justify-content: center; } .doc-canvas { padding: 26px 18px 42px; } .feature-grid { grid-template-columns: 1fr; } .pack-table th:nth-child(3), .pack-table td:nth-child(3) { display: none; } }
